    let ticket3 = shard
        .pending_action_get(run)
        .expect("action should have issued ticket 3");
    let output = ActionOutputReady {
        output_slot: SlotIdx::ZERO,
        value: SlotValue::I64(99),
        taint: Taint::Clean,
        encoded_len: 3,
